<?php
namespace App\Services;
use App\Models\Supplier;
class SupplierSearchService { public function __construct(private SupplierNormalizer $normalizer){} public function search(int $tenantId,string $query,int $limit=8,?string $document=null):array{$doc=$this->normalizer->normalizeDocument($document ?: $query);$name=$this->normalizer->normalizeName($query);$q=Supplier::forTenant($tenantId)->with('aliases')->where(function($x)use($doc,$name){if($doc)$x->where('document',$doc);if($name)$x->orWhere('normalized_name','like',$name.'%')->orWhere('normalized_name','like','%'.$name.'%')->orWhereHas('aliases',fn($a)=>$a->where('normalized_alias','like','%'.$name.'%'));})->limit(30)->get();return $q->map(function($s)use($name,$doc){$alias=$s->aliases->first(fn($a)=>$name!==''&&str_contains($a->normalized_alias,$name));$score=$doc&&$s->document===$doc?100:$this->score($name,$alias?->normalized_alias?:$s->normalized_name);return ['id'=>$s->id,'name'=>$s->displayName(),'legal_name'=>$s->legal_name,'document'=>$s->document,'formatted_document'=>$s->formattedDocument(),'normalized_name'=>$s->normalized_name,'exact_name'=>$name!==''&&$s->normalized_name===$name,'match_type'=>$score===100?'exact':($score>=80?'strong':'possible'),'score'=>$score,'matched_alias'=>$alias?->alias];})->sortByDesc('score')->take($limit)->values()->all();} private function score(string $a,string $b):int{if($a===$b)return 100;$ta=$this->normalizer->searchTokens($a);$tb=$this->normalizer->searchTokens($b);$common=count(array_intersect($ta,$tb));$j=$common/max(1,count(array_unique(array_merge($ta,$tb))));similar_text($a,$b,$sim);return (int)round(max($j*100,$sim));} }
